// cycleWorkflowAPI is deliberately narrower than client.Client. In particular,
// every read is GetNoCache: planning previews, mutation preflight, and
// post-mutation verification must never accept a stale HTTP-cache snapshot.
type cycleWorkflowAPI interface {
	GetNoCache(context.Context, string, map[string]string) (json.RawMessage, error)
	Post(context.Context, string, any) (json.RawMessage, int, error)
}

type cyclePlanOptions struct {
	ProjectID   string
	TargetCycle string
	IssueIDs    []string
	FromBacklog bool
	Limit       int
	DryRun      bool
}

type cycleRolloverOptions struct {
	ProjectID   string
	SourceCycle string
	TargetCycle string
	Limit       int
	DryRun      bool
}

func newWorkflowCyclePlanCmd(flags *rootFlags) *cobra.Command {
	var issueIDs string
	var fromBacklog bool
	var limit int

	cmd := &cobra.Command{
		Use:   "cycle-plan <target_cycle_id> <project_id>",
		Short: "Live-preview and atomically assign selected backlog work items to a cycle.",
		Long: `Build a cycle plan from explicit work-item IDs or automatically from the
project backlog. Automatic selection enumerates every cycle and excludes every
work item already assigned to any cycle. All previews and preflight validation
are live API reads. The final assignment is one atomic bulk request.`,
		Example: `  plane-pp-cli workflow cycle-plan <cycle_id> <project_id> --issue-ids <id-1>,<id-2> --dry-run
  plane-pp-cli workflow cycle-plan <cycle_id> <project_id> --from-backlog --limit 20`,
		Args:        cobra.ExactArgs(2),
		Annotations: map[string]string{"pp:novel": "cycle-plan"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if fromBacklog == (strings.TrimSpace(issueIDs) != "") {
				return usageErr(fmt.Errorf("choose exactly one of --issue-ids or --from-backlog"))
			}
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be positive"))
			}
			slug := effectiveSlug(flags, "")
			if slug == "" || slug == "my-workspace" {
				return usageErr(fmt.Errorf("workspace not set: pass --workspace <slug> or export %s", envWorkspaceSlug))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			applyClientSlug(c, slug)
			result, err := runCyclePlan(cmd.Context(), c, cyclePlanOptions{
				ProjectID:   args[1],
				TargetCycle: args[0],
				IssueIDs:    splitCycleIDs(issueIDs),
				FromBacklog: fromBacklog,
				Limit:       limit,
				DryRun:      flags.dryRun,
			})
			if err != nil {
				return classifyAPIError(err, flags)
			}
			return flags.printJSON(cmd, result)
		},
	}
	cmd.Flags().StringVar(&issueIDs, "issue-ids", "", "Comma-separated work-item UUIDs to validate and assign")
	cmd.Flags().BoolVar(&fromBacklog, "from-backlog", false, "Select work items not assigned to any project cycle")
	cmd.Flags().IntVar(&limit, "limit", 25, "Maximum number of work items to select and live-validate (must be positive)")
	return cmd
}

func newWorkflowCycleHealthCmd(flags *rootFlags) *cobra.Command {
	var limit int
	cmd := &cobra.Command{
		Use:         "cycle-health <cycle_id> <project_id>",
		Short:       "Report live cycle progress, state, priority, and ownership metrics.",
		Args:        cobra.ExactArgs(2),
		Annotations: map[string]string{"pp:novel": "cycle-health", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			slug := effectiveSlug(flags, "")
			if slug == "" || slug == "my-workspace" {
				return usageErr(fmt.Errorf("workspace not set: pass --workspace <slug> or export %s", envWorkspaceSlug))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			applyClientSlug(c, slug)
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be positive"))
			}
			result, err := runCycleHealth(cmd.Context(), c, args[1], args[0], limit)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			return flags.printJSON(cmd, result)
		},
	}
	cmd.Flags().IntVar(&limit, "limit", 100, "Maximum cycle members to live-read for metrics (must be positive)")
	return cmd
}

func newWorkflowCycleRolloverCmd(flags *rootFlags) *cobra.Command {
	var limit int
	cmd := &cobra.Command{
		Use:   "cycle-rollover <source_cycle_id> <target_cycle_id> <project_id>",
		Short: "Live-preview and transfer incomplete work items, then verify both cycles.",
		Long: `Reads both cycle details and memberships live before transfer. In live mode it
uses Plane's atomic transfer endpoint, then bypasses the cache again to verify
that every incomplete source work item moved to the target and left the source.`,
		Args:        cobra.ExactArgs(3),
		Annotations: map[string]string{"pp:novel": "cycle-rollover"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if args[0] == args[1] {
				return usageErr(fmt.Errorf("source and target cycles must differ"))
			}
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be positive"))
			}
			slug := effectiveSlug(flags, "")
			if slug == "" || slug == "my-workspace" {
				return usageErr(fmt.Errorf("workspace not set: pass --workspace <slug> or export %s", envWorkspaceSlug))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			applyClientSlug(c, slug)
			result, err := runCycleRollover(cmd.Context(), c, cycleRolloverOptions{
				ProjectID:   args[2],
				SourceCycle: args[0],
				TargetCycle: args[1],
				Limit:       limit,
				DryRun:      flags.dryRun,
			})
			if err != nil {
				return classifyAPIError(err, flags)
			}
			return flags.printJSON(cmd, result)
		},
	}
	cmd.Flags().IntVar(&limit, "limit", 100, "Maximum source members to live-validate before transfer (must be positive)")
	return cmd
}

func runCyclePlan(ctx context.Context, api cycleWorkflowAPI, opts cyclePlanOptions) (map[string]any, error) {
	if opts.ProjectID == "" || opts.TargetCycle == "" {
		return nil, fmt.Errorf("project and target cycle are required")
	}
	if opts.FromBacklog == (len(opts.IssueIDs) > 0) {
		return nil, fmt.Errorf("choose exactly one explicit or backlog selection mode")
	}
	if opts.Limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}

	targetPath := cycleDetailPath(opts.ProjectID, opts.TargetCycle)
	target, err := api.GetNoCache(ctx, targetPath, nil)
	if err != nil {
		return nil, fmt.Errorf("live target-cycle preview: %w", err)
	}

	selected := uniqueCycleIDs(opts.IssueIDs)
	assignedCount := 0
	if opts.FromBacklog {
		cycles, err := cycleGetAll(ctx, api, cyclesPath(opts.ProjectID))
		if err != nil {
			return nil, fmt.Errorf("listing all cycles for backlog exclusion: %w", err)
		}
		assigned := make(map[string]struct{})
		for _, raw := range cycles {
			cycleID := cycleObjectID(raw)
			if cycleID == "" {
				return nil, fmt.Errorf("cycle list returned an item without an id")
			}
			members, err := cycleGetAll(ctx, api, cycleMembersPath(opts.ProjectID, cycleID))
			if err != nil {
				return nil, fmt.Errorf("listing membership for cycle %s: %w", cycleID, err)
			}
			for _, member := range members {
				if id := cycleMembershipIssueID(member); id != "" {
					assigned[id] = struct{}{}
				}
			}
		}
		assignedCount = len(assigned)

		issues, err := cycleGetAll(ctx, api, cycleIssuesPath(opts.ProjectID))
		if err != nil {
			return nil, fmt.Errorf("listing project backlog candidates: %w", err)
		}
		for _, raw := range issues {
			id := cycleObjectID(raw)
			if id == "" {
				continue
			}
			if _, alreadyCycled := assigned[id]; alreadyCycled {
				continue
			}
			selected = append(selected, id)
			if len(selected) == opts.Limit {
				break
			}
		}
	}
	if len(selected) == 0 {
		return nil, fmt.Errorf("selection is empty after excluding cycle-assigned work items")
	}
	if len(selected) > opts.Limit {
		return nil, fmt.Errorf("selection has %d work items, exceeding --limit %d", len(selected), opts.Limit)
	}

	// Validate every selected work item against the live retrieve endpoint before
	// the one atomic mutation. A stale local row can never authorize assignment.
	for _, issueID := range selected {
		raw, err := api.GetNoCache(ctx, issueDetailPath(opts.ProjectID, issueID), nil)
		if err != nil {
			return nil, fmt.Errorf("live preflight for work item %s: %w", issueID, err)
		}
		if got := cycleObjectID(raw); got != "" && got != issueID {
			return nil, fmt.Errorf("live preflight for work item %s returned %s", issueID, got)
		}
	}

	result := map[string]any{
		"dry_run":               opts.DryRun,
		"project_id":            opts.ProjectID,
		"target_cycle_id":       opts.TargetCycle,
		"selected_issue_ids":    selected,
		"selected_count":        len(selected),
		"already_cycled_count":  assignedCount,
		"target_cycle_preview":  cycleJSONValue(target),
		"selection_source":      map[bool]string{true: "backlog", false: "explicit"}[opts.FromBacklog],
		"live_preflight_passed": true,
	}
	if opts.DryRun {
		return result, nil
	}

	mutationPath := cycleMembersPath(opts.ProjectID, opts.TargetCycle)
	if _, _, err := api.Post(ctx, mutationPath, map[string]any{"issues": selected}); err != nil {
		return nil, fmt.Errorf("atomic cycle assignment: %w", err)
	}
	readback, err := cycleGetAll(ctx, api, mutationPath)
	if err != nil {
		return nil, fmt.Errorf("live target-cycle readback: %w", err)
	}
	present := cycleMembershipIDSet(readback)
	for _, issueID := range selected {
		if _, ok := present[issueID]; !ok {
			return nil, fmt.Errorf("live readback did not contain assigned work item %s", issueID)
		}
	}
	result["verified"] = true
	result["readback_issue_count"] = len(present)
	return result, nil
}

func runCycleHealth(ctx context.Context, api cycleWorkflowAPI, projectID, cycleID string, limit int) (map[string]any, error) {
	if limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}
	cycle, err := api.GetNoCache(ctx, cycleDetailPath(projectID, cycleID), nil)
	if err != nil {
		return nil, fmt.Errorf("reading live cycle: %w", err)
	}
	members, err := cycleGetAll(ctx, api, cycleMembersPath(projectID, cycleID))
	if err != nil {
		return nil, fmt.Errorf("reading live cycle work items: %w", err)
	}
	if len(members) > limit {
		return nil, fmt.Errorf("cycle has %d members, exceeding --limit %d; raise --limit to inspect all members", len(members), limit)
	}
	issues := make([]json.RawMessage, 0, len(members))
	for _, member := range members {
		issueID := cycleMembershipIssueID(member)
		if issueID == "" {
			return nil, fmt.Errorf("cycle membership returned without a work-item id")
		}
		issue, err := api.GetNoCache(ctx, issueDetailPath(projectID, issueID), nil)
		if err != nil {
			return nil, fmt.Errorf("reading live work item %s for cycle health: %w", issueID, err)
		}
		issues = append(issues, issue)
	}
	metrics := aggregateCycleHealth(issues)
	metrics["cycle"] = cycleJSONValue(cycle)
	metrics["cycle_id"] = cycleID
	metrics["project_id"] = projectID
	metrics["source"] = "live"
	return metrics, nil
}

func runCycleRollover(ctx context.Context, api cycleWorkflowAPI, opts cycleRolloverOptions) (map[string]any, error) {
	if opts.SourceCycle == opts.TargetCycle {
		return nil, fmt.Errorf("source and target cycles must differ")
	}
	if opts.Limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}
	source, err := api.GetNoCache(ctx, cycleDetailPath(opts.ProjectID, opts.SourceCycle), nil)
	if err != nil {
		return nil, fmt.Errorf("live source-cycle preview: %w", err)
	}
	target, err := api.GetNoCache(ctx, cycleDetailPath(opts.ProjectID, opts.TargetCycle), nil)
	if err != nil {
		return nil, fmt.Errorf("live target-cycle preview: %w", err)
	}
	sourceMembers, err := cycleGetAll(ctx, api, cycleMembersPath(opts.ProjectID, opts.SourceCycle))
	if err != nil {
		return nil, fmt.Errorf("live source membership preview: %w", err)
	}
	targetMembers, err := cycleGetAll(ctx, api, cycleMembersPath(opts.ProjectID, opts.TargetCycle))
	if err != nil {
		return nil, fmt.Errorf("live target membership preview: %w", err)
	}
	if len(sourceMembers) > opts.Limit {
		return nil, fmt.Errorf("source cycle has %d members, exceeding --limit %d; raise --limit to validate the full transfer", len(sourceMembers), opts.Limit)
	}
	movable := make([]string, 0, len(sourceMembers))
	for _, member := range sourceMembers {
		issueID := cycleMembershipIssueID(member)
		if issueID == "" {
			return nil, fmt.Errorf("source cycle membership returned without a work-item id")
		}
		issue, err := api.GetNoCache(ctx, issueDetailPath(opts.ProjectID, issueID), nil)
		if err != nil {
			return nil, fmt.Errorf("live rollover preflight for work item %s: %w", issueID, err)
		}
		if !cycleItemCompleted(issue) {
			movable = append(movable, issueID)
		}
	}
	sort.Strings(movable)

	result := map[string]any{
		"dry_run":                   opts.DryRun,
		"project_id":                opts.ProjectID,
		"source_cycle_id":           opts.SourceCycle,
		"target_cycle_id":           opts.TargetCycle,
		"source_cycle_preview":      cycleJSONValue(source),
		"target_cycle_preview":      cycleJSONValue(target),
		"source_issue_count_before": len(cycleMembershipIDSet(sourceMembers)),
		"target_issue_count_before": len(cycleMembershipIDSet(targetMembers)),
		"movable_issue_ids":         movable,
		"movable_issue_count":       len(movable),
		"live_preview_complete":     true,
	}
	if opts.DryRun {
		return result, nil
	}

	transferPath := fmt.Sprintf("/projects/%s/cycles/%s/transfer-issues/", opts.ProjectID, opts.SourceCycle)
	if _, _, err := api.Post(ctx, transferPath, map[string]any{"new_cycle_id": opts.TargetCycle}); err != nil {
		return nil, fmt.Errorf("atomic cycle rollover: %w", err)
	}

	// Read both detail and membership endpoints again. The detail reads are not
	// redundant: they confirm neither cycle disappeared or became inaccessible
	// during the operation, while membership reads verify the transferred set.
	if _, err := api.GetNoCache(ctx, cycleDetailPath(opts.ProjectID, opts.SourceCycle), nil); err != nil {
		return nil, fmt.Errorf("live source-cycle readback: %w", err)
	}
	if _, err := api.GetNoCache(ctx, cycleDetailPath(opts.ProjectID, opts.TargetCycle), nil); err != nil {
		return nil, fmt.Errorf("live target-cycle readback: %w", err)
	}
	sourceAfter, err := cycleGetAll(ctx, api, cycleMembersPath(opts.ProjectID, opts.SourceCycle))
	if err != nil {
		return nil, fmt.Errorf("live source membership readback: %w", err)
	}
	targetAfter, err := cycleGetAll(ctx, api, cycleMembersPath(opts.ProjectID, opts.TargetCycle))
	if err != nil {
		return nil, fmt.Errorf("live target membership readback: %w", err)
	}
	sourceSet, targetSet := cycleMembershipIDSet(sourceAfter), cycleMembershipIDSet(targetAfter)
	for _, issueID := range movable {
		if _, remains := sourceSet[issueID]; remains {
			return nil, fmt.Errorf("rollover verification: incomplete work item %s remains in source cycle", issueID)
		}
		if _, arrived := targetSet[issueID]; !arrived {
			return nil, fmt.Errorf("rollover verification: incomplete work item %s is absent from target cycle", issueID)
		}
	}
	result["source_issue_count_after"] = len(sourceSet)
	result["target_issue_count_after"] = len(targetSet)
	result["verified"] = true
	return result, nil
}

func cycleGetAll(ctx context.Context, api cycleWorkflowAPI, path string) ([]json.RawMessage, error) {
	var all []json.RawMessage
	cursor := ""
	seenCursors := map[string]struct{}{}
	for {
		params := map[string]string{"per_page": "100"}
		if cursor != "" {
			params["cursor"] = cursor
		}
		data, err := api.GetNoCache(ctx, path, params)
		if err != nil {
			return nil, err
		}
		items, next, hasMore := extractPageItems(data, "cursor")
		all = append(all, items...)
		if !hasMore || next == "" {
			return all, nil
		}
		if _, repeated := seenCursors[next]; repeated {
			return nil, fmt.Errorf("pagination repeated cursor %q", next)
		}
		seenCursors[next] = struct{}{}
		cursor = next
	}
}

func aggregateCycleHealth(items []json.RawMessage) map[string]any {
	byPriority := map[string]int{}
	byStateGroup := map[string]int{}
	completed, unassigned := 0, 0
	for _, raw := range items {
		var item map[string]any
		if json.Unmarshal(raw, &item) != nil {
			continue
		}
		priority := cycleString(item["priority"])
		if priority == "" {
			priority = "none"
		}
		byPriority[priority]++
		group := cycleStateGroup(item)
		if group == "" {
			group = "unknown"
		}
		byStateGroup[group]++
		if cycleItemCompleted(raw) {
			completed++
		}
		if cycleAssigneeCount(item) == 0 {
			unassigned++
		}
	}
	total := len(items)
	progress := 0.0
	if total > 0 {
		progress = float64(completed) * 100 / float64(total)
	}
	return map[string]any{
		"total":          total,
		"completed":      completed,
		"incomplete":     total - completed,
		"unassigned":     unassigned,
		"completion_pct": progress,
		"by_priority":    byPriority,
		"by_state_group": byStateGroup,
	}
}

func cycleItemCompleted(raw json.RawMessage) bool {
	var item map[string]any
	if json.Unmarshal(raw, &item) != nil {
		return false
	}
	if v := cycleString(item["completed_at"]); v != "" {
		return true
	}
	switch strings.ToLower(cycleStateGroup(item)) {
	case "completed", "cancelled", "canceled":
		return true
	default:
		return false
	}
}

func cycleStateGroup(item map[string]any) string {
	if group := cycleString(item["state_group"]); group != "" {
		return group
	}
	if state, ok := item["state_detail"].(map[string]any); ok {
		return cycleString(state["group"])
	}
	if state, ok := item["state"].(map[string]any); ok {
		return cycleString(state["group"])
	}
	return ""
}

func cycleAssigneeCount(item map[string]any) int {
	for _, key := range []string{"assignees", "assignee_details"} {
		if values, ok := item[key].([]any); ok {
			return len(values)
		}
	}
	return 0
}

func cycleObjectID(raw json.RawMessage) string {
	var item map[string]any
	if json.Unmarshal(raw, &item) != nil {
		return ""
	}
	for _, key := range []string{"id", "issue_id", "work_item_id"} {
		if id := cycleString(item[key]); id != "" {
			return id
		}
	}
	for _, key := range []string{"issue", "work_item", "data", "result"} {
		if nested, ok := item[key].(map[string]any); ok {
			if id := cycleString(nested["id"]); id != "" {
				return id
			}
		}
	}
	return ""
}

// cycleMembershipIssueID normalizes Plane's CycleIssue representations. A
// membership row's own "id" is not the work-item id, so "issue" must win when
// present (as either a scalar UUID or an expanded object).
func cycleMembershipIssueID(raw json.RawMessage) string {
	var item map[string]any
	if json.Unmarshal(raw, &item) != nil {
		return ""
	}
	if issue := cycleString(item["issue"]); issue != "" {
		return issue
	}
	if issue, ok := item["issue"].(map[string]any); ok {
		if id := cycleString(issue["id"]); id != "" {
			return id
		}
	}
	for _, key := range []string{"issue_id", "work_item_id"} {
		if id := cycleString(item[key]); id != "" {
			return id
		}
	}
	return cycleString(item["id"])
}

func cycleMembershipIDSet(items []json.RawMessage) map[string]struct{} {
	out := make(map[string]struct{}, len(items))
	for _, raw := range items {
		if id := cycleMembershipIssueID(raw); id != "" {
			out[id] = struct{}{}
		}
	}
	return out
}

func splitCycleIDs(csv string) []string {
	if strings.TrimSpace(csv) == "" {
		return nil
	}
	return uniqueCycleIDs(strings.Split(csv, ","))
}

func uniqueCycleIDs(ids []string) []string {
	out := make([]string, 0, len(ids))
	seen := make(map[string]struct{}, len(ids))
	for _, raw := range ids {
		id := strings.TrimSpace(raw)
		if id == "" {
			continue
		}
		if _, ok := seen[id]; ok {
			continue
		}
		seen[id] = struct{}{}
		out = append(out, id)
	}
	return out
}

func cycleString(v any) string {
	s, _ := v.(string)
	return strings.TrimSpace(s)
}

func cycleJSONValue(raw json.RawMessage) any {
	var out any
	if json.Unmarshal(raw, &out) != nil {
		return string(raw)
	}
	return out
}

func cyclesPath(projectID string) string {
	return fmt.Sprintf("/projects/%s/cycles/", projectID)
}

func cycleDetailPath(projectID, cycleID string) string {
	return fmt.Sprintf("/projects/%s/cycles/%s/", projectID, cycleID)
}

func cycleMembersPath(projectID, cycleID string) string {
	return fmt.Sprintf("/projects/%s/cycles/%s/cycle-issues/", projectID, cycleID)
}

func cycleIssuesPath(projectID string) string {
	return fmt.Sprintf("/projects/%s/issues/", projectID)
}

func issueDetailPath(projectID, issueID string) string {
	return fmt.Sprintf("/projects/%s/issues/%s/", projectID, issueID)
}

var _ cycleWorkflowAPI = (*client.Client)(nil)
